RECORDED_ETA = "// Explicit isolated training fixture; native customer-visible history note only.\n// No carrier, SMTP, payment or other external service is called.\nrequire '/var/www/magento2/app/bootstrap.php';\n$s=json_decode($argv[1],true,512,JSON_THROW_ON_ERROR);$b=\\Magento\\Framework\\App\\Bootstrap::create(BP,$_SERVER);$o=$b->getObjectManager();$o->get(\\Magento\\Framework\\App\\State::class)->setAreaCode('frontend');\nif(!preg_match('/^\\d{9}$/',$s['order_number'])||!preg_match('/^\\d{4}-\\d{2}-\\d{2}$/',$s['date']))throw new RuntimeException('Exact recorded order/date required');\n$e=include BP.'/app/etc/env.php';$d=$e['db']['connection']['default'];$host=explode(':',$d['host']);$pdo=new PDO('mysql:host='.$host[0].';port='.$host[1].';dbname='.$d['dbname'],$d['username'],$d['password']);$pdo->setAttribute(PDO::ATTR_ERRMODE,PDO::ERRMODE_EXCEPTION);\nfunction rows($sql,$args=[]){global $pdo;$q=$pdo->prepare($sql);$q->execute($args);return$q->fetchAll(PDO::FETCH_ASSOC);}\n$users=rows('SELECT entity_id FROM customer_entity WHERE email=?',[$s['email']]);if(count($users)!==1)throw new RuntimeException('Unique native customer missing');$uid=(int)$users[0]['entity_id'];$orders=rows('SELECT * FROM sales_order WHERE customer_id=? AND increment_id=?',[$uid,$s['order_number']]);if(count($orders)!==1)throw new RuntimeException('Exact owned native order absent');$order=$orders[0];$oid=(int)$order['entity_id'];$note='Recorded estimated delivery date: '.$s['date'];\n$existing=rows('SELECT * FROM sales_order_status_history WHERE parent_id=? AND comment=?',[$oid,$note]);\nif($s['operation']==='initialize'){\n if($existing)throw new RuntimeException('Declared new native training note already exists');\n $history=$o->get(\\Magento\\Sales\\Model\\Order\\Status\\HistoryFactory::class)->create();$history->setParentId($oid)->setStatus($order['status'])->setComment($note)->setIsCustomerNotified(0)->setIsVisibleOnFront(1)->setEntityName('order')->setCreatedAt($order['created_at']);$o->get(\\Magento\\Sales\\Model\\ResourceModel\\Order\\Status\\History::class)->save($history);\n $current=rows('SELECT * FROM sales_order WHERE entity_id=?',[$oid]);if($current!==$orders)throw new RuntimeException('Training note must not change original order row');\n $existing=rows('SELECT * FROM sales_order_status_history WHERE parent_id=? AND comment=?',[$oid,$note]);\n}else if($s['operation']!=='read')throw new RuntimeException('Unsupported native fixture operation');\nif(count($existing)!==1||(int)$existing[0]['is_visible_on_front']!==1||(int)$existing[0]['is_customer_notified']!==0||$existing[0]['entity_name']!=='order')throw new RuntimeException('Exact visible native recorded-date note missing');\n$source=['vendor/magento/module-sales/Model/Order/Status/History.php','vendor/magento/module-sales/Model/ResourceModel/Order/Status/History.php','vendor/magento/module-sales/view/frontend/templates/order/order_comments.phtml'];$hashes=[];foreach($source as$f){if(!is_file(BP.'/'.$f))throw new RuntimeException('Native history implementation missing');$hashes[$f]=hash_file('sha256',BP.'/'.$f);}\necho json_encode(['order_id'=>$oid,'order_number'=>$s['order_number'],'customer_id'=>$uid,'date'=>$s['date'],'order'=>$order,'history_note'=>$existing[0],'native_history_rows'=>rows('SELECT * FROM sales_order_status_history WHERE parent_id=? ORDER BY entity_id',[$oid]),'initialized_native_visible_note'=>true,'fixture_version'=>'native-local-recorded-order-date-v1','source_hashes'=>$hashes,'external_delivery'=>false],JSON_THROW_ON_ERROR);\n"

PROTECTION = "// Default output remains hashes only. An explicit private directory can retain\n// quote/address JSONL bytes from the same cursor used for each table digest.\n$rawDir=$argv[1]??null;\nif($rawDir!==null&&(!is_dir($rawDir)||!is_writable($rawDir)))throw new RuntimeException('Private evidence directory unavailable');\n$env=include '/var/www/magento2/app/etc/env.php';$d=$env['db']['connection']['default'];$h=explode(':',$d['host']);\n$p=new PDO('mysql:host='.$h[0].';port='.$h[1].';dbname='.$d['dbname'],$d['username'],$d['password'],[PDO::ATTR_ERRMODE=>PDO::ERRMODE_EXCEPTION,PDO::ATTR_EMULATE_PREPARES=>false]);\n$version=$p->query('SELECT VERSION()')->fetchColumn();$p->exec(stripos($version,'MariaDB')!==false?'SET SESSION max_statement_time=20':'SET SESSION max_execution_time=20000');\n$tables=['customer_entity','customer_entity_datetime','customer_entity_decimal','customer_entity_int','customer_entity_text','customer_entity_varchar','customer_address_entity','customer_address_entity_datetime','customer_address_entity_decimal','customer_address_entity_int','customer_address_entity_text','customer_address_entity_varchar','sales_order','sales_order_item','sales_order_address','sales_order_payment','quote_item','quote_item_option','salesrule','salesrule_coupon','salesrule_customer_group','salesrule_website','quote','quote_address','quote_payment','sales_order_status_history','review','review_detail','review_store','review_entity_summary','rating_option_vote'];\n$out=[];$p->exec('START TRANSACTION READ ONLY');\nforeach($tables as$t){\n $keys=$p->query(\"SHOW KEYS FROM `$t` WHERE Key_name='PRIMARY'\")->fetchAll(PDO::FETCH_ASSOC);usort($keys,fn($a,$b)=>$a['Seq_in_index']<=>$b['Seq_in_index']);$pk=array_column($keys,'Column_name');\n if(!$pk)throw new RuntimeException('Declared protected native table lacks primary key');\n $cols=$p->query(\"SHOW COLUMNS FROM `$t`\")->fetchAll(PDO::FETCH_ASSOC);$columns=array_column($cols,'Field');\n // Every timestamp and all remaining columns of every protected row remain covered.\n $ignored=[];$hash=hash_init('sha256');$count=0;$last=null;$chunks=0;$sink=null;\n if($rawDir!==null&&in_array($t,['quote','quote_address'],true)){\n  $sink=fopen($rawDir.'/'.$t.'.jsonl','xb');if($sink===false)throw new RuntimeException('Private evidence file already exists or cannot be opened');\n  if(!chmod($rawDir.'/'.$t.'.jsonl',0600))throw new RuntimeException('Private evidence permissions failed');\n }\n while(true){$order=implode(',',array_map(fn($x)=>'`'.$x.'`',$pk));$sql=\"SELECT * FROM `$t`\";\n  if($last!==null)$sql.=' WHERE ('.$order.')>('.implode(',',array_fill(0,count($pk),'?')).')';\n  $sql.=' ORDER BY '.$order.' LIMIT 1024';$q=$p->prepare($sql);$q->execute($last??[]);$n=0;\n  while($row=$q->fetch(PDO::FETCH_ASSOC)){$last=array_map(fn($k)=>$row[$k],$pk);foreach($ignored as$k)unset($row[$k]);$bytes=json_encode($row,JSON_THROW_ON_ERROR).\"\\n\";\n   if($sink!==null&&fwrite($sink,$bytes)!==strlen($bytes))throw new RuntimeException('Incomplete private evidence write');\n   hash_update($hash,$bytes);$count++;$n++;}\n  $q->closeCursor();$chunks++;fwrite(STDERR,'LAB_PROTECTED_PROGRESS '.json_encode(['table'=>$t,'rows'=>$count,'chunk'=>$chunks]).\"\\n\");if($n<1024)break;\n }\n if($sink!==null){if(!fflush($sink))throw new RuntimeException('Private evidence flush failed');fclose($sink);}\n $native=(int)$p->query(\"SELECT COUNT(*) FROM `$t`\")->fetchColumn();if($native!==$count)throw new RuntimeException('Incomplete full protected table coverage');\n $out[$t]=['rows'=>$count,'sha256'=>hash_final($hash),'primary_key'=>$pk,'columns'=>$columns,'ignored_columns'=>$ignored,'chunks'=>$chunks];\n}\n$p->exec('ROLLBACK');echo json_encode(['version'=>'shopping-complete-native-query-full-rows-v1','tables'=>$out,'coverage'=>'Every row and column of explicit account/address/order/payment/cart/coupon/history/review tables. No ignored columns. Sessions, visitors, guest compare collection and authentication log are mutable runtime metadata and not claimed protected.','statement_budget_seconds'=>20],JSON_THROW_ON_ERROR);\n"
